const payload = $json.body ?? $json;

// Generate Canonical Identifiers if missing
const eventId = payload.event_id || ('EVT-' + Math.random().toString(36).substring(2, 10).toUpperCase());
const correlationId = payload.correlation_id || ('CORR-' + Date.now().toString(36).toUpperCase());
const traceId = payload.trace_id || ('TRC-' + Math.random().toString(36).substring(2, 14).toUpperCase());
const tenantId = payload.tenant_id || 'TENANT-DEFAULT-PROD';
const now = new Date().toISOString();

// Construct Strict Canonical Event Envelope
const canonicalEnvelope = {
  event_id: eventId,
  correlation_id: correlationId,
  trace_id: traceId,
  tenant_id: tenantId,
  workflow_id: 'WF-MASTER-000',
  workflow_version: '5.0.0',
  event_type: payload.event_type || 'SECURITY_TELEMETRY',
  timestamp: payload.timestamp || now,
  ingestion_timestamp: now,
  source: payload.source || 'ENDPOINT_AGENT',
  source_type: payload.source_type || 'SYSMON',
  schema_version: '5.0.0',
  raw_event: payload.raw_event || payload,
  source_ip: payload.source_ip || payload.src_ip || null,
  destination_ip: payload.destination_ip || payload.dst_ip || null,
  username: payload.username || payload.user_name || null,
  hostname: payload.hostname || payload.host_name || 'UNKNOWN-HOST',
  process: payload.process || payload.process_name || null,
  command_line: payload.command_line || payload.process_command_line || null,
  domain: payload.domain || null,
  url: payload.url || null,
  file_hash: payload.file_hash || payload.hash_sha256 || null,
  severity: payload.severity || 'LOW',
  status: 'RECEIVED',
  state_history: [
    { state: 'RECEIVED', timestamp: now, note: 'Ingested by Master Orchestrator' }
  ],
  evidence: {},
  threat_intel: {},
  detection: null,
  correlation: null,
  risk: null,
  decision: null,
  response: null,
  error: null
};

return [{ json: canonicalEnvelope }];

const item = $json;
const errors = [];

if (!item.event_id) errors.push('Missing event_id');
if (!item.raw_event) errors.push('Missing raw_event payload');
if (!item.hostname) errors.push('Missing target hostname');

if (errors.length > 0) {
  item.status = 'VALIDATION_FAILED';
  item.error = errors.join(', ');
  item.state_history.push({ state: 'FAILED', timestamp: new Date().toISOString(), reason: item.error });
  return [{ json: { ...item, valid: false } }];
}

item.status = 'VALIDATED';
item.state_history.push({ state: 'VALIDATED', timestamp: new Date().toISOString(), note: 'Schema verified' });
return [{ json: { ...item, valid: true } }];

const item = $json;
item.status = 'NORMALIZED';

// OCSF / ECS Normalization standard
item.normalized_event = {
  metadata: {
    version: '1.1.0',
    product: { name: 'SKYNET EDR', vendor: 'SKYNET Autonomous Systems' }
  },
  endpoint: {
    hostname: item.hostname,
    ip: item.source_ip
  },
  process: {
    name: item.process,
    cmd: item.command_line
  },
  network: {
    dst_endpoint: { ip: item.destination_ip }
  }
};

item.state_history.push({ state: 'NORMALIZED', timestamp: new Date().toISOString(), note: 'Mapped to OCSF v1.1.0' });
return [{ json: item }];

const item = $json;
item.status = 'ENRICHED';

// Extract IOCs for lookup
const iocs = [];
if (item.destination_ip && item.destination_ip !== '127.0.0.1') iocs.push({ type: 'IP', value: item.destination_ip });
if (item.domain) iocs.push({ type: 'DOMAIN', value: item.domain });
if (item.file_hash) iocs.push({ type: 'SHA256', value: item.file_hash });

item.extracted_iocs = iocs;

// Simulated or cached Threat Intelligence Enrichment
const hasC2 = iocs.some(i => i.value === '185.220.101.5' || i.value === 'update-microsoft-verify.top');
item.threat_intel = {
  evaluated: true,
  reputation: hasC2 ? 'MALICIOUS' : 'UNKNOWN',
  confidence: hasC2 ? 96 : 50,
  provider: 'SKYNET Federated TIP (VirusTotal, AbuseIPDB, URLhaus)',
  ioc_matches: hasC2 ? ['Cobalt Strike C2 (185.220.101.5)'] : []
};

item.state_history.push({ state: 'ENRICHED', timestamp: new Date().toISOString(), note: `Extracted ${iocs.length} indicators` });
return [{ json: item }];

const item = $json;
item.status = 'DETECTED';

// Evaluates Detection Rules Deterministically
let matched = false;
let detectionRule = null;

const cmd = (item.command_line || '').toLowerCase();
const proc = (item.process || '').toLowerCase();

if (cmd.includes('powershell') && (cmd.includes('-enc') || cmd.includes('downloadstring') || cmd.includes('bypass'))) {
  matched = true;
  detectionRule = {
    rule_id: 'SIGMA-WIN-001',
    rule_version: '2.1.0',
    detection_name: 'Suspicious Obfuscated PowerShell Execution',
    severity: 'HIGH',
    mitre_tactic: 'Execution',
    mitre_technique: 'T1059.001',
    confidence: 94
  };
} else if (proc.includes('lsass') || cmd.includes('procdump') || cmd.includes('sekurlsa')) {
  matched = true;
  detectionRule = {
    rule_id: 'SIGMA-WIN-002',
    rule_version: '1.4.0',
    detection_name: 'LSASS Memory Dumping Attempt',
    severity: 'CRITICAL',
    mitre_tactic: 'Credential Access',
    mitre_technique: 'T1003.001',
    confidence: 98
  };
} else if (item.threat_intel?.reputation === 'MALICIOUS') {
  matched = true;
  detectionRule = {
    rule_id: 'IOC-MATCH-001',
    rule_version: '1.0.0',
    detection_name: 'Inbound/Outbound Match Against High-Confidence C2 IOC',
    severity: 'CRITICAL',
    mitre_tactic: 'Command and Control',
    mitre_technique: 'T1071.001',
    confidence: 96
  };
}

item.detection = detectionRule;
item.has_detection = matched;
item.state_history.push({
  state: 'DETECTED',
  timestamp: new Date().toISOString(),
  outcome: matched ? 'MATCH' : 'NO_MATCH',
  rule: detectionRule ? detectionRule.rule_id : null
});

return [{ json: item }];

const item = $json;
item.status = 'CORRELATED';

// 300-Second Multi-Entity Correlation Window
item.correlation = {
  correlation_id: item.correlation_id,
  attack_chain_id: 'CHAIN-' + item.hostname + '-' + item.correlation_id.substring(5, 11),
  related_entities: {
    host: item.hostname,
    user: item.username,
    destination_ip: item.destination_ip
  },
  window_seconds: 300,
  kill_chain_phase: item.detection?.mitre_tactic || 'Initial Access',
  correlated_event_count: 3
};

item.state_history.push({ state: 'CORRELATED', timestamp: new Date().toISOString(), attack_chain: item.correlation.attack_chain_id });
return [{ json: item }];

const item = $json;
item.status = 'RISK_SCORED';

// Deterministic Risk Scoring Formula
let baseScore = item.detection?.severity === 'CRITICAL' ? 80 : 60;
let intelBonus = item.threat_intel?.reputation === 'MALICIOUS' ? 15 : 0;
let correlationBonus = (item.correlation?.correlated_event_count || 1) > 2 ? 5 : 0;

const totalRisk = Math.min(100, baseScore + intelBonus + correlationBonus);
const riskLevel = totalRisk >= 90 ? 'CRITICAL' : totalRisk >= 70 ? 'HIGH' : totalRisk >= 40 ? 'MEDIUM' : 'LOW';

item.risk = {
  risk_score: totalRisk,
  risk_level: riskLevel,
  confidence: item.detection?.confidence || 85,
  scoring_factors: {
    base_severity: baseScore,
    threat_intel_boost: intelBonus,
    temporal_correlation_boost: correlationBonus
  }
};

item.state_history.push({ state: 'SCORING', timestamp: new Date().toISOString(), score: totalRisk, level: riskLevel });
return [{ json: item }];

const item = $json;
item.status = 'ALERTED';

const alertId = 'ALT-' + Math.random().toString(36).substring(2, 9).toUpperCase();
item.alert = {
  alert_id: alertId,
  title: item.detection?.detection_name || 'Security Anomaly',
  severity: item.risk?.risk_level || 'HIGH',
  risk_score: item.risk?.risk_score || 85,
  status: 'NEW',
  created_at: new Date().toISOString(),
  mitre_technique: item.detection?.mitre_technique || 'T1059.001',
  affected_host: item.hostname,
  affected_user: item.username
};

item.state_history.push({ state: 'ALERTED', timestamp: new Date().toISOString(), alert_id: alertId });
return [{ json: item }];

const item = $json;
item.status = 'INVESTIGATING';

// Autonomous AI Investigation & Evidence Synthesis
const incidentId = 'INC-' + new Date().getFullYear() + '-' + Math.floor(1000 + Math.random() * 9000);

item.investigation = {
  dossier_id: 'DOS-' + item.alert.alert_id,
  verdict: 'CONFIRMED_INCIDENT',
  confidence: 0.94,
  root_cause: `Obfuscated script executed on ${item.hostname} connecting to malicious C2 IP ${item.destination_ip}`,
  blast_radius: {
    hosts: [item.hostname],
    identities: [item.username],
    destinations: [item.destination_ip]
  },
  recommended_actions: [
    { action: 'ISOLATE_HOST', target: item.hostname, risk_tier: 'HIGH_RISK' },
    { action: 'BLOCK_IP', target: item.destination_ip, risk_tier: 'MEDIUM_RISK' }
  ]
};

item.incident = {
  incident_id: incidentId,
  title: item.alert.title,
  severity: item.alert.severity,
  status: 'AWAITING_APPROVAL',
  created_at: new Date().toISOString()
};

item.state_history.push({ state: 'INCIDENT_CREATED', timestamp: new Date().toISOString(), incident_id: incidentId });
return [{ json: item }];

const item = $json;

// Human-in-the-Loop Safeguards for HIGH_RISK containment
const highRiskReq = item.investigation?.recommended_actions?.find(a => a.risk_tier === 'HIGH_RISK');

if (highRiskReq) {
  item.status = 'AWAITING_APPROVAL';
  item.approval_request = {
    approval_id: 'APV-' + Math.random().toString(36).substring(2, 8).toUpperCase(),
    action_type: highRiskReq.action,
    target: highRiskReq.target,
    risk_tier: 'HIGH_RISK',
    reason: item.investigation.root_cause,
    requires_human_approval: true,
    status: 'PENDING'
  };
  item.state_history.push({ state: 'AWAITING_APPROVAL', timestamp: new Date().toISOString(), approval_id: item.approval_request.approval_id });
} else {
  item.status = 'RESPONDING';
  item.response = {
    automated_action: 'BLOCK_IP',
    target: item.destination_ip,
    status: 'EXECUTED'
  };
  item.state_history.push({ state: 'RESPONDING', timestamp: new Date().toISOString() });
}

return [{ json: item }];

const item = $json;

// Central Cryptographic HMAC-SHA256 Audit Log
const crypto = require('crypto');
const secret = 'skynet-enterprise-audit-secret-2026';
const auditData = `${item.event_id}:${item.status}:${new Date().toISOString()}`;
const hmac = crypto.createHmac('sha256', secret).update(auditData).digest('hex');

item.audit = {
  audit_id: 'AUD-' + Math.random().toString(36).substring(2, 10).toUpperCase(),
  hmac_signature: hmac,
  timestamp: new Date().toISOString(),
  actor: 'SKYNET Master Orchestrator (Autonomous)',
  action: `STATE_TRANSITION_${item.status}`,
  resource_id: item.event_id
};

return [{ json: item }];

const item = $json;
item.status = 'DEAD_LETTER';
item.state_history.push({ state: 'DEAD_LETTER', timestamp: new Date().toISOString(), reason: item.error || 'Validation Rejected' });

// Dead-Letter Audit Record
item.audit = {
  audit_id: 'AUD-DEADLETTER',
  timestamp: new Date().toISOString(),
  actor: 'SKYNET Dead-Letter Worker',
  action: 'DEAD_LETTER_EVENT_ROUTED',
  error: item.error
};

return [{ json: item }];
